    "type": "integer"
   }
  ]
 },
 {
  "kind": "buy-boxed-pencils",
  "description": "A shop buys boxed pencils from the factory.",
  "fields": [
   {
    "name": "buyer",
    "type": "entity_ref"
   },
   {
    "name": "seller",
    "type": "entity_ref"
   },
   {
    "name": "quantity",
    "type": "integer"
   }
  ]
 },
 {
  "kind": "sell-pencil",
  "description": "Sell a pencil from shop stock to a customer for the listed pencil price.",
  "fields": [
   {
    "name": "shop",
    "type": "entity_ref"
   },
   {
    "name": "customer",
